const paths = ["package.json","release/local-signoff.json","website/package.json"];
const results = await Promise.allSettled(paths.map(p => tools.read_file({ path: p })));
const out = {};
results.forEach((r, i) => {
  if (r.status === "fulfilled") {
    const v = r.value;
    out[paths[i]] = typeof v === "string" ? v : v.content;
  } else {
    out[paths[i]] = "ERROR: " + r.reason.message;
  }
});
return out;

